        if len(current_code) == 1 << n:
            return current_code

        last_bit_string = current_code[-1]
        next_bits = []

        for bit in '01':
            new_bit_string = last_bit_string + bit
            hamming_distance = sum(c1 != c2 for c1, c2 in zip(last_bit_string, new_bit_string))

            if hamming_distance in P and new_bit_string not in current_code:
                next_bits.append(new_bit_string)

        for next_bit in next_bits:
